result=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/idempotency/IdempotencyResult.java'),encoding:'UTF-8');store=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/idempotency/JdbcIdempotencyStore.java'),encoding:'UTF-8');migration=File.read(File.join(root,'database/migrations/V20260823_05__idempotency_result_model.sql'),encoding:'UTF-8')
checks={code:result.match?(/int code/)&&migration.include?('response_code'),data:result.match?(/R data/)&&store.include?('response_payload'),resultVersion:result.include?('resultVersion')&&migration.include?('response_version'),schemaVersion:result.include?('schemaVersion')&&migration.include?('response_schema_version'),ttl:result.include?('expiresAt')&&store.include?('expires_at'),query:store.include?('findResult'),persistence:store.include?('saveResult')}
